import numpy as np
from rcb_robowits import Session

INSTANCE = '/app/instance.json'
OUT = '/app/output/trajectory.npz'

def quat_from_R(R):
    from scipy.spatial.transform import Rotation
    q = Rotation.from_matrix(np.asarray(R, dtype=float)).as_quat() # xyzw
    return np.array([q[3], q[0], q[1], q[2]], dtype=float)

def horiz_push_quat():
    return quat_from_R([[0,0,1],[1,0,0],[0,1,0]])

def q14_from_action(a):
    return np.r_[np.asarray(a)[0:7], np.asarray(a)[9:16]]

def solve_pose(s, arm, pos, quat, seed14):
    tip = 'Gripper_Tip_R' if arm == 'right' else 'Gripper_Tip_L'
    res = s.kinematics({'op':'ik','targets':{tip:[*map(float,pos),*map(float,quat)]},'seed':seed14.tolist(),'max_iters':300,'tol_pos_m':0.015,'tol_rot_rad':0.2})
    if not res['ok']:
        e=res.get('error',{}).get(tip,{})
        raise RuntimeError(f'IK failed {arm} {np.round(pos,3)}: {e}')
    return np.asarray(res['q']),res['error'][tip]

def joint_move(s,p,arm,q14,steps=30,settle=0):
    a=s.hold_action()
    qarm=q14[0:7] if arm=='right' else q14[7:14]
